package com.crypto.laplace.config;import static org.assertj.core.api.Assertions.*;import org.junit.jupiter.api.Test;
class LaplacePaperSafetyConfigurationTest {@Test void liveModeIsAlwaysRejected(){var p=new LaplaceStrategyProperties();p.setExecutionMode("LIVE");assertThatThrownBy(p::validatePhaseOne).hasMessageContaining("PAPER");}@Test void legacyAndLaplaceExecutionCannotCoexist(){var p=new LaplaceStrategyProperties();p.setOldStrategyEnabled(true);p.getLaplace().setPaperExecutionEnabled(true);assertThatThrownBy(p::validatePhaseOne).isInstanceOf(IllegalStateException.class);}@Test void sizingAndStartupConstantsAreValidated(){var p=new LaplaceStrategyProperties();p.getLaplace().setLeverage(2);assertThatThrownBy(p::validatePhaseOne).hasMessageContaining("paper execution");}}
